package cli

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"strings"
	"text/tabwriter"

	"github.com/spf13/cobra"
	"golang.org/x/term"

	"github.com/SemRels/semrel/internal/colors"
)

var styledOutput bool

func useStyledOutput(format string) bool {
	return format == "text" && os.Getenv("CI") == "" &&
		term.IsTerminal(int(os.Stdout.Fd())) && term.IsTerminal(int(os.Stderr.Fd()))
}

func tableWriter(hasHeader bool) (*tabwriter.Writer, func() error) {
	if !styledOutput || !hasHeader {
		w := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
		return w, w.Flush
	}
	var buf bytes.Buffer
	w := tabwriter.NewWriter(&buf, 0, 0, 2, ' ', 0)
	return w, func() error {
		if err := w.Flush(); err != nil {
			return err
		}
		header, body, found := strings.Cut(buf.String(), "\n")
		if !found {
			_, err := fmt.Fprint(os.Stdout, colors.Cyan(header))
			return err
		}
		_, err := fmt.Fprint(os.Stdout, colors.Cyan(header)+"\n"+body)
		return err
	}
}

func promptMarker() string {
	if styledOutput {
		return colors.Cyan("?")
	}
	return "?"
}

func pluginStage(phase, ref string) string {
	if phase != "release" || !strings.HasPrefix(ref, "@semrel/") {
		return phase
	}
	name := strings.TrimPrefix(ref, "@semrel/")
	for _, category := range []string{"provider", "publisher", "packager", "hook"} {
		if strings.HasPrefix(name, category+"-") {
			return category
		}
	}
	return phase
}

func styleCommandErrors(cmd *cobra.Command) {
	if run := cmd.RunE; run != nil {
		cmd.RunE = func(cmd *cobra.Command, args []string) error {
			err := run(cmd, args)
			if err != nil && styledOutput {
				writeStatus(os.Stderr, "✗", cmd.Name(), err.Error())
				cmd.SilenceErrors = true
			}
			return err
		}
	}
	for _, child := range cmd.Commands() {
		styleCommandErrors(child)
	}
}

func writeStatus(w io.Writer, marker, label, message string) {
	switch marker {
	case "✓":
		marker = colors.Green(marker)
	case "✗":
		marker = colors.Red(marker)
	case "⚠":
		marker = colors.Yellow(marker)
	default:
		marker = colors.Cyan(marker)
	}
	fmt.Fprintf(w, "%s %-10s %s\n", marker, label, message)
}

// printStatus preserves legacy output for scripts, redirected output, and CI.
func printStatus(w io.Writer, marker, label, message, legacy string) {
	if styledOutput {
		writeStatus(w, marker, label, message)
	} else {
		_, _ = fmt.Fprint(w, legacy)
	}
}
